arguments.command:
# Has dynamic symbols! Let's try to resolve addresses using the dynamic symbol table
# The offsets from the tombstone are:
# #01 pc 0x222098
# #02 pc 0x222234
# #03 pc 0x19bac0
# #06 pc 0x19bc14

# Use addr2line with the binary (even stripped, dynsym might help, or we can use nm -D)
# First let's see if we can get function names from dynamic symbols near those addresses
readelf --dyn-syms /tmp/libmonosgen-2.0.so 2>/dev/null | awk '{print $2, $8}' | sort | grep -v "^$" | awk -v addr1="0x222098" -v addr2="0x222234" -v addr3="0x19bac0" -v addr4="0x19bc14" '
BEGIN { 
    targets[1] = strtonum("0x222098"); targets[2] = strtonum("0x222234"); 
    targets[3] = strtonum("0x19bac0"); targets[4] = strtonum("0x19bc14")
}
/^[0-9a-f]/ { 
    val = strtonum("0x" $1)
    if (val > 0) {
        for (i = 1; i <= 4; i++) {
            if (val <= targets[i] && (val > best_val[i] || best_val[i] == 0)) {
                best_val[i] = val; best_name[i] = $2
            }
        }
    }
}
END {
    for (i = 1; i <= 4; i++) printf "0x%x -> %s+0x%x\n", targets[i], best_name[i], targets[i] - best_val[i]
}' 2>/dev/null

