arguments.command:
# Those offsets are very large - probably wrong base symbol. Let me get a tighter match with sizes
nm -D --defined-only -S /tmp/libmonosgen-2.0.so 2>/dev/null | sort | awk '
{
    if (NF == 4) { val = strtonum("0x" $1); size = strtonum("0x" $2); sym = $4 }
    else { val = strtonum("0x" $1); size = 0; sym = $3 }
    syms[val] = sym; szs[val] = size; addrs[++n] = val
}
END {
    targets[1] = strtonum("0x222098"); targets[2] = strtonum("0x222234")
    targets[3] = strtonum("0x19bac0"); targets[4] = strtonum("0x19bc14")
    for (t = 1; t <= 4; t++) {
        best = 0
        for (i = 1; i <= n; i++) {
            if (addrs[i] <= targets[t]) best = addrs[i]
            else break
        }
        if (best > 0) {
            offset = targets[t] - best
            printf "0x%x -> %s+0x%x", targets[t], syms[best], offset
            if (szs[best] > 0 && offset > szs[best]) printf " (OUTSIDE symbol boundary, size=0x%x)", szs[best]
            printf "\n"
        }
    }
}'

