# The addresses fall between exported symbols - likely in static/internal functions not in dynsym.
# Let me find the closest symbols that actually contain these addresses
nm -D --defined-only -S /tmp/libmonosgen-2.0.so 2>/dev/null | sort | awk '
{
    if (NF == 4) { val = strtonum("0x" $1); size = strtonum("0x" $2); sym = $4 }
    else { val = strtonum("0x" $1); size = 0; sym = $3 }
    if (size > 0) { syms[val] = sym; szs[val] = size; addrs[++n] = val }
}
END {
    targets[1] = strtonum("0x222098"); targets[2] = strtonum("0x222234")
    targets[3] = strtonum("0x19bac0"); targets[4] = strtonum("0x19bc14")
    for (t = 1; t <= 4; t++) {
        best = 0
        for (i = 1; i <= n; i++) {
            if (addrs[i] <= targets[t] && (addrs[i] + szs[addrs[i]]) > targets[t]) {
                best = addrs[i]; break
            }
        }
        if (best > 0) {
            printf "0x%x -> %s+0x%x (size=0x%x)\n", targets[t], syms[best], targets[t] - best, szs[best]
        } else {
            # Find surrounding symbols
            prev = 0; next_v = 0
            for (i = 1; i <= n; i++) {
                if (addrs[i] <= targets[t]) prev = addrs[i]
                if (addrs[i] > targets[t] && next_v == 0) next_v = addrs[i]
            }
            printf "0x%x -> (no containing symbol) prev: %s@0x%x+0x%x, next: %s@0x%x\n", targets[t], syms[prev], prev, szs[prev], syms[next_v], next_v
        }
    }
}'

