        for (i = 1; i <= n; i++) {
            if (addrs[i] <= targets[t] && (addrs[i] + szs[addrs[i]]) > targets[t]) {
                best = addrs[i]; break
            }
        }
        if (best > 0) {
            printf "0x%x -> %s+0x%x (size=0x%x)\n", targets[t], syms[best], targets[t] - best, szs[best]
        } else {
            # Find surrounding symbols
            prev = 0; next_v = 0
            for (i = 1; i <= n; i++) {
                if (addrs[i] <= targets[t]) prev = addrs[i]
                if (addrs[i] > targets[t] && next_v == 0) next_v = addrs[i]
            }
            printf "0x%x -> (no containing symbol) prev: %s@0x%x+0x%x, next: %s@0x%x\n", targets[t], syms[prev], prev, szs[prev], syms[next_v], next_v
        }
    }
}'

